import{_ as e,o as i,c as n,a5 as c}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Định nghĩa file plan.md","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/definition/plan.md","filePath":"feature/system-maintenance/definition/plan.md"}'),a={name:"feature/system-maintenance/definition/plan.md"};function o(d,t,h,r,l,s){return i(),n("div",null,[...t[0]||(t[0]=[c('<h1 id="đinh-nghia-file-plan-md" tabindex="-1">Định nghĩa file <code>plan.md</code> <a class="header-anchor" href="#đinh-nghia-file-plan-md" aria-label="Permalink to &quot;Định nghĩa file `plan.md`&quot;">​</a></h1><h2 id="muc-đich" tabindex="-1">Mục đích <a class="header-anchor" href="#muc-đich" aria-label="Permalink to &quot;Mục đích&quot;">​</a></h2><p><code>plan.md</code> trả lời câu hỏi <strong>&quot;Kỹ thuật triển khai như thế nào&quot;</strong> — dịch nghiệp vụ trong <code>spec.md</code> thành thiết kế cụ thể: động chạm file/module nào, schema nào, API contract final, thứ tự implement ra sao. Đây là bước dev tự thiết kế trước khi viết code thật, để review được trước khi tốn công code sai hướng.</p><h2 id="ai-viet-khi-nao-viet" tabindex="-1">Ai viết, khi nào viết <a class="header-anchor" href="#ai-viet-khi-nao-viet" aria-label="Permalink to &quot;Ai viết, khi nào viết&quot;">​</a></h2><p>Dev được giao task viết, <strong>sau khi <code>spec.md</code> đã ở trạng thái confirmed</strong> (không viết plan cho spec còn Draft/chưa rõ). Viết trước khi code, không viết song song hoặc sau khi code xong (mất tác dụng review trước).</p><h2 id="noi-dung-can-co" tabindex="-1">Nội dung cần có <a class="header-anchor" href="#noi-dung-can-co" aria-label="Permalink to &quot;Nội dung cần có&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Liên kết</td><td>Link tới <code>spec.md</code> cùng FR, tóm tắt 1 câu lại mục tiêu</td></tr><tr><td>Phạm vi kỹ thuật</td><td>Repo/service nào bị động (business-service, ai-service, web-dashboard...), file/module chính sẽ tạo hoặc sửa</td></tr><tr><td>API Contract (final)</td><td>Method, path, request/response schema thật — chốt lại từ đề xuất ở <code>spec.md</code>, khác gì thì ghi rõ vì sao</td></tr><tr><td>Data Model</td><td>Bảng/collection nào đọc/viết, field nào mới cần thêm, migration cần không</td></tr><tr><td>Luồng xử lý</td><td>Bước xử lý chính ở backend/frontend (business logic, validation, side-effect) — không cần pseudo-code chi tiết, chỉ cần đủ để review đúng-sai logic</td></tr><tr><td>Dependencies</td><td>Feature/API/service nào phải xong trước; feature nào bị chặn bởi cái này</td></tr><tr><td>Rủi ro kỹ thuật</td><td>Chỗ dễ sai, cần cẩn thận (concurrency, third-party rate limit, migration dữ liệu cũ...)</td></tr></tbody></table><h2 id="ranh-gioi-voi-cac-file-khac" tabindex="-1">Ranh giới với các file khác <a class="header-anchor" href="#ranh-gioi-voi-cac-file-khac" aria-label="Permalink to &quot;Ranh giới với các file khác&quot;">​</a></h2><ul><li>Không lặp lại nghiệp vụ đã có trong <code>spec.md</code> — chỉ link tới, không copy AC.</li><li>Không chẻ nhỏ ra từng bước code cụ thể (đó là việc của <code>task.md</code>) — <code>plan.md</code> là thiết kế, <code>task.md</code> là checklist thực thi.</li><li>Nếu lúc code phát hiện thiết kế trong <code>plan.md</code> sai/thiếu → sửa <code>plan.md</code> trước khi tiếp tục code, giữ file luôn phản ánh đúng cái đang code.</li></ul>',9)])])}const u=e(a,[["render",o]]);export{m as __pageData,u as default};
